import React, { useState, useEffect } from 'react';
import './Retrait.css';
import VerifierPin from './VerifierPin';

function Retrait({ allerVers, utilisateur }) {
  const [soldes, setSoldes] = useState({ mtn: 0, airtel: 0, total: 0 });
  const [retraits, setRetraits] = useState([]);
  const [operateur, setOperateur] = useState('mtn');
  const [montant, setMontant] = useState('');
  const [message, setMessage] = useState('');
  const [chargement, setChargement] = useState(false);
  const [pinVerifie, setPinVerifie] = useState(false);
  const [etape, setEtape] = useState('formulaire');

  useEffect(() => {
    if (utilisateur) {
      fetch(`/api/retraits/${utilisateur.id}`)
        .then(res => res.json())
        .then(data => {
          setSoldes(data.soldes);
          setRetraits(data.retraits);
        });
    }
  }, [utilisateur]);

  const handleRetrait = async () => {
    setMessage('');

    if (!montant || parseInt(montant) < 500) {
      setMessage('❌ Le montant minimum est 500 FCFA !');
      return;
    }

    if (operateur === 'mtn' && !utilisateur.numero_mtn) {
      setMessage('❌ Vous n\'avez pas de numéro MTN. Ajoutez-le dans Mon Compte !');
      return;
    }

    if (operateur === 'airtel' && !utilisateur.numero_airtel) {
      setMessage('❌ Vous n\'avez pas de numéro Airtel. Ajoutez-le dans Mon Compte !');
      return;
    }

    setChargement(true);

    try {
      const reponse = await fetch('/api/retraits', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          artiste_id: utilisateur.id,
          operateur,
          montant: parseInt(montant)
        })
      });

      const donnees = await reponse.json();

      if (reponse.ok) {
        setEtape('succes');
        setMessage('✅ ' + donnees.message);
        fetch(`/api/retraits/${utilisateur.id}`)
          .then(res => res.json())
          .then(data => {
            setSoldes(data.soldes);
            setRetraits(data.retraits);
          });
      } else {
        setMessage('❌ ' + donnees.message);
      }
    } catch (erreur) {
      setMessage('❌ Impossible de contacter le serveur');
    }

    setChargement(false);
  };

  if (!pinVerifie) {
    return (
      <VerifierPin
        utilisateur={utilisateur}
        titre="Accès Retrait"
        onSuccess={() => setPinVerifie(true)}
        onCancel={() => allerVers('dashboard')}
      />
    );
  }

  return (
    <div className="retrait-page">
      <header className="header">
        <div className="logo" onClick={() => allerVers('accueil')}>🎵 Varim Music</div>
        <nav className="nav">
          <a href="#" onClick={() => allerVers('accueil')}>Accueil</a>
          <a href="#" onClick={() => allerVers('dashboard')}>Dashboard</a>
        </nav>
        <div className="auth-buttons">
          <span className="user-prenom">👋 {utilisateur?.prenom}</span>
        </div>
      </header>

      <div className="retrait-contenu">
        <h1 className="retrait-titre">💸 Retirer mes gains</h1>

        <div className="soldes-grille">
          <div className="solde-carte total">
            <div className="solde-icone">💰</div>
            <div className="solde-valeur">{soldes.total} FCFA</div>
            <div className="solde-label">Total disponible</div>
          </div>
          <div className="solde-carte mtn">
            <div className="solde-icone">🟡</div>
            <div className="solde-valeur">{soldes.mtn} FCFA</div>
            <div className="solde-label">Gains MTN</div>
            {utilisateur?.numero_mtn && (
              <div className="solde-numero">+242 {utilisateur.numero_mtn}</div>
            )}
          </div>
          <div className="solde-carte airtel">
            <div className="solde-icone">🔴</div>
            <div className="solde-valeur">{soldes.airtel} FCFA</div>
            <div className="solde-label">Gains Airtel</div>
            {utilisateur?.numero_airtel && (
              <div className="solde-numero">+242 {utilisateur.numero_airtel}</div>
            )}
          </div>
        </div>

        <div className="retrait-box">
          <h2>Nouvelle demande de retrait</h2>

          {message && (
            <div className={`retrait-message ${etape === 'succes' ? 'succes' : 'erreur'}`}>
              {message}
            </div>
          )}

          {etape === 'succes' ? (
            <div className="succes-box">
              <div className="succes-icone">🎉</div>
              <p>Votre demande a été enregistrée ! Vous recevrez vos gains sur votre numéro {operateur.toUpperCase()} sous 24-48h.</p>
              <button className="btn-nouveau-retrait" onClick={() => { setEtape('formulaire'); setMontant(''); setMessage(''); }}>
                Faire un autre retrait
              </button>
              <button className="btn-retour-dashboard" onClick={() => allerVers('dashboard')}>
                ← Retour au Dashboard
              </button>
            </div>
          ) : (
            <>
              <div className="retrait-champ">
                <label>Choisir l'opérateur</label>
                <div className="operateurs-retrait">
                  <div
                    className={`operateur-retrait ${operateur === 'mtn' ? 'active' : ''} ${!utilisateur?.numero_mtn ? 'desactive' : ''}`}
                    onClick={() => utilisateur?.numero_mtn && setOperateur('mtn')}
                  >
                    <span className="op-logo mtn">MTN</span>
                    <span>Mobile Money</span>
                    <span className="op-solde">{soldes.mtn} FCFA</span>
                    {!utilisateur?.numero_mtn && (
                      <span className="op-warning">⚠️ Numéro non configuré</span>
                    )}
                  </div>
                  <div
                    className={`operateur-retrait ${operateur === 'airtel' ? 'active' : ''} ${!utilisateur?.numero_airtel ? 'desactive' : ''}`}
                    onClick={() => utilisateur?.numero_airtel && setOperateur('airtel')}
                  >
                    <span className="op-logo airtel">Airtel</span>
                    <span>Money</span>
                    <span className="op-solde">{soldes.airtel} FCFA</span>
                    {!utilisateur?.numero_airtel && (
                      <span className="op-warning">⚠️ Numéro non configuré</span>
                    )}
                  </div>
                </div>
              </div>

              <div className="retrait-champ">
                <label>Montant à retirer (FCFA)</label>
                <input
                  type="number"
                  placeholder="Ex: 5000"
                  value={montant}
                  onChange={(e) => setMontant(e.target.value)}
                  min="500"
                  max={operateur === 'mtn' ? soldes.mtn : soldes.airtel}
                />
                <small className="aide">
                  Minimum : 500 FCFA — Disponible : {operateur === 'mtn' ? soldes.mtn : soldes.airtel} FCFA
                </small>
              </div>

              {operateur === 'mtn' && utilisateur?.numero_mtn && (
                <div className="retrait-destination">
                  🟡 Sera envoyé sur : <strong>+242 {utilisateur.numero_mtn}</strong>
                </div>
              )}
              {operateur === 'airtel' && utilisateur?.numero_airtel && (
                <div className="retrait-destination">
                  🔴 Sera envoyé sur : <strong>+242 {utilisateur.numero_airtel}</strong>
                </div>
              )}

              <button
                className="retrait-btn"
                onClick={handleRetrait}
                disabled={chargement}
              >
                {chargement ? 'Traitement...' : `Retirer ${montant || 0} FCFA via ${operateur.toUpperCase()}`}
              </button>

              <button className="btn-configurer" onClick={() => allerVers('mon-compte')}>
                ⚙️ Configurer mes numéros Mobile Money
              </button>
            </>
          )}
        </div>

        {retraits.length > 0 && (
          <div className="historique-retraits">
            <h2>📋 Historique des retraits</h2>
            <table className="retrait-table">
              <thead>
                <tr>
                  <th>Date</th>
                  <th>Opérateur</th>
                  <th>Montant</th>
                  <th>Numéro</th>
                  <th>Statut</th>
                </tr>
              </thead>
              <tbody>
                {retraits.map(retrait => (
                  <tr key={retrait.id}>
                    <td>{new Date(retrait.date_demande).toLocaleDateString('fr-FR')}</td>
                    <td>
                      <span className={`badge-op ${retrait.operateur}`}>
                        {retrait.operateur.toUpperCase()}
                      </span>
                    </td>
                    <td className="montant-retrait">{retrait.montant} FCFA</td>
                    <td>+242 {retrait.numero_retrait}</td>
                    <td>
                      <span className={`statut ${retrait.statut}`}>
                        {retrait.statut === 'en_attente' ? '⏳ En attente' :
                         retrait.statut === 'traite' ? '✅ Traité' : '❌ Annulé'}
                      </span>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>
    </div>
  );
}

export default Retrait;
